import * as React from "react"
import { adminCall } from "./admin-call"
import { GO_LIVE, GO_LIVE_GROUPS } from "../../data/go-live"
import * as s from "./GoLive.module.css"

/**
 * Admin → Go-live — FCS-117.
 * ============================================================================
 * Every thing that has to be true for the site to be operational, each with a
 * LIVE measurement from the admin-golive function and, when it is not green, the
 * exact steps. What each item means lives in src/data/go-live.js, which also
 * generates docs/GO-LIVE.md, so this screen and the document cannot disagree.
 *
 * "Re-check" asks the server again. Nothing here writes, sends or spends.
 */

const WORDS = {
  pass: "Ready",
  warn: "Needs attention",
  fail: "Broken",
  blocked: "Waiting",
  untested: "Untested",
  todo: "Not built",
}

const GoLive = () => {
  const [results, setResults] = React.useState(null)
  const [ranAt, setRanAt] = React.useState("")
  const [busy, setBusy] = React.useState(false)
  const [problem, setProblem] = React.useState("")

  const run = React.useCallback(async () => {
    setBusy(true)
    const res = await adminCall("admin-golive", {})
    setBusy(false)
    if (!res.ok) {
      setProblem(res.body.message || `Could not run the checks (HTTP ${res.status}).`)
      return
    }
    setProblem("")
    setResults(res.body.results)
    setRanAt(res.body.ranAt)
  }, [])

  React.useEffect(() => {
    run()
  }, [run])

  const count = status => GO_LIVE.filter(item => results?.[item.id]?.status === status).length
  const ready = count("pass")
  const pct = Math.round((ready / GO_LIVE.length) * 100)

  return (
    <div className={s.wrap} data-testid="go-live">
      <div className={s.top}>
        <div>
          <p className={s.score} data-testid="go-live-score">
            <strong>{results ? ready : "…"}</strong> of {GO_LIVE.length} ready
          </p>
          <p className={s.tally}>
            {results
              ? ["fail", "warn", "blocked", "untested", "todo"]
                  .filter(k => count(k))
                  .map(k => `${count(k)} ${WORDS[k].toLowerCase()}`)
                  .join(" · ") || "Everything is ready."
              : "Measuring…"}
          </p>
        </div>
        <button type="button" className={s.button} onClick={run} disabled={busy}>
          {busy ? "Checking…" : "Re-check"}
        </button>
      </div>
      <div className={s.bar} role="img" aria-label={`${ready} of ${GO_LIVE.length} ready`}>
        <span style={{ width: `${pct}%` }} />
      </div>
      {ranAt ? <p className={s.fine}>Last measured {new Date(ranAt).toLocaleTimeString()}. Every check only reads: nothing is sent, written or bought.</p> : null}
      {problem ? <p className={s.error}>{problem}</p> : null}

      {GO_LIVE_GROUPS.map(group => (
        <section key={group.id} className={s.group}>
          <h2 className={s.h2}>{group.title}</h2>
          <p className={s.lead}>{group.lead}</p>
          {GO_LIVE.filter(item => item.group === group.id).map(item => {
            const r = results?.[item.id]
            const status = r?.status || "pending"
            const open = status !== "pass" && status !== "pending"
            return (
              <article key={item.id} className={s.item} data-status={status} data-testid={`go-${item.id}`}>
                <header className={s.head}>
                  <h3 className={s.h3}>{item.title}</h3>
                  <span className={s.pill} data-status={status}>
                    {WORDS[status] || "…"}
                  </span>
                </header>
                {r ? <p className={s.detail}>{r.detail}</p> : <span className={s.skel} />}
                <p className={s.owner}>{item.owner}</p>
                <details open={open} className={s.more}>
                  <summary>{status === "pass" ? "If this ever goes red" : "Why it matters and what to do"}</summary>
                  <p className={s.why}>{item.why}</p>
                  <ol className={s.steps}>
                    {item.steps.map(step => (
                      <li key={step}>{step}</li>
                    ))}
                  </ol>
                </details>
              </article>
            )
          })}
        </section>
      ))}
    </div>
  )
}

export default GoLive
