import { apiUrl } from "../../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../../config/supabase-public"
import { supabase } from "../../lib/supabase"

/**
 * Calls an admin function as whoever is signed in — FCS-095.
 *
 * Returns `{ ok, status, body }` and never throws: every admin screen has to
 * say something useful when the answer is a refusal, and a rejected promise is
 * the wrong shape for "this account is not an administrator".
 */
export async function adminCall(name, body) {
  const client = supabase()
  const { data } = client ? await client.auth.getSession() : { data: null }
  const token = data?.session?.access_token

  try {
    const res = await fetch(apiUrl(name), {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        apikey: SUPABASE_PUBLISHABLE_KEY,
        Authorization: `Bearer ${token || SUPABASE_PUBLISHABLE_KEY}`,
      },
      body: JSON.stringify(body),
    })
    return { ok: res.ok, status: res.status, body: await res.json().catch(() => ({})) }
  } catch {
    return { ok: false, status: 0, body: { message: "Could not reach the server. Check your connection." } }
  }
}
